// Packs vendor/sql-wasm.wasm into vendor/sql-wasm-b64.js so the page also works from a double-clicked
// index.html (file://), where browsers refuse to fetch a sibling .wasm. Re-run after upgrading sql.js.
import fs from 'node:fs'; import path from 'node:path'; import crypto from 'node:crypto';
const dir = path.dirname(new URL(import.meta.url).pathname);
const bytes = fs.readFileSync(path.join(dir, 'sql-wasm.wasm'));
const sha = crypto.createHash('sha256').update(bytes).digest('hex');
const out = `// sql.js 1.10.2 — sql-wasm.wasm as base64 (generated by vendor/pack.mjs; do not edit)\n// sha256 of the decoded bytes: ${sha}\nwindow.SQL_WASM_B64 = "${bytes.toString('base64')}";\n`;
fs.writeFileSync(path.join(dir, 'sql-wasm-b64.js'), out);
console.log('vendor/sql-wasm-b64.js written', out.length, 'chars; wasm sha256', sha);
